import json, pandas as pd
from datetime import date, timedelta

df = pd.read_csv('data/context/payments.csv')
merchants = json.load(open('data/context/merchant_data.json'))
fees = json.load(open('data/context/fees.json'))

def get_merchant(name):
    for m in merchants:
        if m['merchant']==name:
            return m

def capture_bucket(cd):
    if cd in ('manual','immediate'):
        return cd
    d = int(cd)
    if d < 3: return '<3'
    if d <=5: return '3-5'
    return '>5'

def day_of_year_to_month(day, year):
    d = date(year,1,1) + timedelta(days=day-1)
    return d.month

def fraud_bucket(rate_pct):
    if rate_pct < 7.2: return '<7.2%'
    if rate_pct < 7.7: return '7.2%-7.7%'
    if rate_pct < 8.3: return '7.7%-8.3%'
    return '>8.3%'

def volume_bucket(v):
    if v < 100000: return '<100k'
    if v < 1000000: return '100k-1m'
    if v < 5000000: return '1m-5m'
    return '>5m'

def monthly_stats(merchant, year, month):
    d = df[df['merchant']==merchant].copy()
    d['month'] = d['day_of_year'].apply(lambda x: day_of_year_to_month(x, year))
    sub = d[(d['year']==year) & (d['month']==month)]
    total = sub['eur_amount'].sum()
    fraud = sub.loc[sub['has_fraudulent_dispute'], 'eur_amount'].sum()
    rate = fraud/total*100 if total else 0
    return sub, total, rate

def wildcard_match(val, allowed):
    # allowed: list -> [] or None means wildcard; else membership
    if allowed is None:
        return True
    if isinstance(allowed, list):
        if len(allowed)==0:
            return True
        return val in allowed
    return val == allowed

def fee_merchant_level_match(fee, account_type, mcc, capture_delay_bucket, fraud_bucket_val, vol_bucket_val):
    if fee['account_type'] and account_type not in fee['account_type']:
        return False
    if fee['merchant_category_code'] and mcc not in fee['merchant_category_code']:
        return False
    if fee['capture_delay'] is not None and fee['capture_delay'] != capture_delay_bucket:
        return False
    if fee['monthly_fraud_level'] is not None and fee['monthly_fraud_level'] != fraud_bucket_val:
        return False
    if fee['monthly_volume'] is not None and fee['monthly_volume'] != vol_bucket_val:
        return False
    return True

def fee_txn_level_match(fee, card_scheme, is_credit, aci, intracountry):
    if fee['card_scheme'] is not None and fee['card_scheme'] != card_scheme:
        return False
    if fee['is_credit'] is not None and fee['is_credit'] != is_credit:
        return False
    if fee['aci'] and aci not in fee['aci']:
        return False
    if fee['intracountry'] is not None and bool(fee['intracountry']) != intracountry:
        return False
    return True

def applicable_fees_for(merchant_name, year, month, day=None):
    m = get_merchant(merchant_name)
    cap = capture_bucket(m['capture_delay'])
    sub, total, rate = monthly_stats(merchant_name, year, month)
    fb = fraud_bucket(rate)
    vb = volume_bucket(total)
    if day is not None:
        sub = sub[sub['day_of_year']==day]
    merchant_ok = [f for f in fees if fee_merchant_level_match(f, m['account_type'], m['merchant_category_code'], cap, fb, vb)]
    applicable = set()
    for _, txn in sub.iterrows():
        intracountry = txn['issuing_country'] == txn['acquirer_country']
        for f in merchant_ok:
            if fee_txn_level_match(f, txn['card_scheme'], bool(txn['is_credit']), txn['aci'], intracountry):
                applicable.add(f['ID'])
    return sorted(applicable), fb, vb, total, rate

# Task 1681: day 10, 2023
res, fb, vb, total, rate = applicable_fees_for('Belles_cookbook_store', 2023, 1, day=10)
print('1681 result', res, fb, vb, rate)
gold1681 = {741, 709, 454, 813, 381, 536, 473, 572, 477, 286}
